import {Component, HostBinding, OnInit} from '@angular/core';
import {ActivatedRoute, NavigationExtras, Router} from '@angular/router';

import {NavController, Platform} from '@ionic/angular';
import {routeAnimation} from '../../shared';
import {HttpClientService} from '../../shared/http-client.service';
import {isNotNullOrUndefined} from 'codelyzer/util/isNotNullOrUndefined';

import { Plugins } from '@capacitor/core';
// 扫描码
import 'scanner';
import {environment} from "../../../environments/environment";
import {ModalService} from 'ng-zorro-antd-mobile';
const { Scanner } = Plugins;
@Component({
    selector: 'app-box-list',
    templateUrl: 'box-list.page.html',
    styleUrls: ['box-list.page.scss'],
    animations: [    // 路由动画
        routeAnimation
    ]
})
export class BoxListPage implements OnInit{
    BoxListList = [];
    load;
    constructor(
        private router: Router,
        public navCtrl: NavController,
        private http: HttpClientService,
        private route: ActivatedRoute,
        private platform: Platform,
        private alertModal: ModalService,
    ) {
        // 控制app返回按钮
        this.platform.backButton.subscribeWithPriority(10, () => {
            this.routeBack();
        });
    }

    @HostBinding('@routeAnimation') state;   // 路由动画
    ngOnInit() {
        this.load = document.getElementsByClassName('box-load-bar')[0];
    }
    ionViewWillEnter() {
        // 获取箱列表
        this.GetBoxList();
    }
    // 路由返回
    routeBack() {
        this.router.navigate(['/tabs/tab1']);
    }
    // 路由跳转
    routeFont(barcode, boxBarId, boxState, index) {
        sessionStorage.setItem('boxBarcode', barcode);
        sessionStorage.setItem('boxBarId', boxBarId);
        if (index === 0){
        if (boxState === 'OpenBox') {
            sessionStorage.setItem('isCloseBox', '0');
        } else {
            if (boxState === 'CloseBox'){
                this.alertModal.alert('封箱状态', '该箱处于封箱状态，是否确认开箱?', [
                    { text: '取消', onPress: () => {
                            sessionStorage.setItem('isCloseBox', '1');
                            this.router.navigate(['/BottleList']);
                        } },
                    {
                        text: '确定', onPress: () => {
                            const condition = {
                                boxBarcode: barcode,
                                boxState: 'OpenBox'
                            };
                            this.http
                                .get(`rcp/api/box/operate/scan`, condition, '扫描转运箱条码', environment.FailMessage.openBox, {load: true})
                                .subscribe(data => {
                                    if (data['isSuccess']) {
                                        sessionStorage.setItem('isCloseBox', '0');
                                        sessionStorage.setItem('boxBarcode', data['data']['boxBarcode']);
                                        sessionStorage.setItem('boxBarId', data['data']['boxBarId']);
                                        this.router.navigate(['/BottleList']);
                                    }
                                });
                        }
                    },
                ]);
                return;
            }
        }
        } else {
            sessionStorage.setItem('isCloseBox', '1');
        }
        this.router.navigate(['/BottleList']);
    }
    clickScan() {
        this.router.navigate(['/tabs/tab1']);
    }
    // 调用后台接口
    // 1. 获取当前箱列表
    GetBoxList(){
        this.BoxListList = [];
        this.http
            .get(`rcp/api/box/operate/getBoxListByUser`, {} ,
                '获取当前箱列表', environment.FailMessage.getBoxList, {load: true})
            .subscribe( data => {
                if (data['isSuccess']){
                      this.BoxListList = data['data'];
                      this.BoxListList.forEach(w => {
                          w.openTime = this.transDate(w.openTime);
                          w.closeTime = this.transDate(w.closeTime);
                      });
                    }
            });
    }

     transDate(date) {
        if (isNotNullOrUndefined(date)){
            var tt = new Date(parseInt(date));
            // @ts-ignore
            var days = parseInt((new Date().getTime() - date) / 86400000);
            var today = new Date().getDate();
            var year = tt.getFullYear();
            var mouth = tt.getMonth() + 1;
            var day = tt.getDate();
            var time = tt.getHours() < 10 ? '0' + tt.getHours() : tt.getHours();
            var min = tt.getMinutes() < 10 ? '0' + tt.getMinutes() : tt.getMinutes();
            var result, offset;
            offset = Math.abs(today - day);
            if (days < 3 && offset < 3) {
                if (offset === 0) {
                    result = '今天' + ' ' + time + ':' + min;
                } else if (offset === 1) {
                    result = '昨天' + ' ' + time + ':' + min;
                } else if (offset === 2) {
                    result = '前天' + ' ' + time + ':' + min;
                }
            } else {
                result = year + '-' + mouth + '-' + day + ' ' + time + ':' + min;
            }
            return result;
        } else {
            return '暂无';
        }
    }
    // 封箱操作
    confirmBox(barcode, $event){
        $event.stopPropagation();
        const condition = {
            boxBarcode: barcode,
            boxState: 'CloseBox'
        };
        this.http
            .get(`rcp/api/box/operate/scan`, condition , '扫描转运箱条码', environment.FailMessage.confirmBox, {load: true})
            .subscribe( data => {
                if (data['isSuccess']){
                   this.GetBoxList();
                }
            });
    }
    OpenBoxOperate(barcode) {
        const condition = {
            boxBarcode: barcode,
            boxState: 'OpenBox'
        };
        this.http
            .get(`rcp/api/box/operate/scan`, condition, '扫描转运箱条码', environment.FailMessage.openBox, {load: true})
            .subscribe(data => {
                if (data['isSuccess']) {
                    sessionStorage.setItem('isCloseBox', '0');
                    sessionStorage.setItem('boxBarcode', data['data']['boxBarcode']);
                    sessionStorage.setItem('boxBarId', data['data']['boxBarId']);
                    this.router.navigate(['/BottleBarcode']);
                }
            });
    }
}
